import 'dart:math' as math;import 'package:flutter/material.dart';import '../models/battle_v4_models.dart';
class RadialCommandV4 extends StatelessWidget{const RadialCommandV4({super.key,required this.center,required this.radius,required this.selected,required this.onSelected});final Offset center;final double radius;final V4ActionCategory selected;final ValueChanged<V4ActionCategory> onSelected;@override Widget build(BuildContext context){const e=<(V4ActionCategory,IconData,double)>[(V4ActionCategory.attack,Icons.local_fire_department,-90),(V4ActionCategory.control,Icons.auto_fix_high,0),(V4ActionCategory.defense,Icons.shield_outlined,90),(V4ActionCategory.tool,Icons.science_outlined,180)];return Stack(children:[for(final x in e)_circle(center:_polar(center,radius,x.$3),selected:x.$1==selected,semantics:x.$1.label,onTap:()=>onSelected(x.$1),child:Icon(x.$2,size:25,color:Colors.white))]);}}
class SkillRadialV4 extends StatelessWidget{const SkillRadialV4({super.key,required this.center,required this.radius,required this.skills,required this.selectedId,required this.onSkill,required this.onBack});final Offset center;final double radius;final List<V4SkillChoice> skills;final String? selectedId;final ValueChanged<String> onSkill;final VoidCallback onBack;@override Widget build(BuildContext context){final n=skills.length;return Stack(children:[for(var i=0;i<n;i++)_circle(center:_polar(center,radius,n==1?-90:-140+(100*i/(n-1))),selected:skills[i].id==selectedId,semantics:skills[i].label,onTap:()=>onSkill(skills[i].id),child:Text(skills[i].shortLabel,textAlign:TextAlign.center,style:const TextStyle(fontSize:9,fontWeight:FontWeight.bold))),Positioned(left:center.dx-20,top:center.dy-20,width:40,height:40,child:Material(color:const Color(0xE62B2E39),shape:const CircleBorder(),child:InkWell(customBorder:const CircleBorder(),onTap:onBack,child:const Icon(Icons.arrow_back,size:19))))]);}}
class RadialMoveButtonV4 extends StatelessWidget{const RadialMoveButtonV4({super.key,required this.center,required this.radius,required this.active,required this.enabled,required this.onTap});final Offset center;final double radius;final bool active,enabled;final VoidCallback onTap;@override Widget build(BuildContext context)=>Positioned(left:center.dx-29,top:center.dy+radius+5,width:58,height:30,child:Material(color:!enabled?const Color(0x8822242C):active?const Color(0xFF356D9D):const Color(0xE6222430),borderRadius:BorderRadius.circular(15),child:InkWell(borderRadius:BorderRadius.circular(15),onTap:enabled?onTap:null,child:const Center(child:Text('MOVE',style:TextStyle(fontSize:9,fontWeight:FontWeight.bold))))));}
Offset _polar(Offset c,double r,double d){final a=d*math.pi/180;return Offset(c.dx+math.cos(a)*r,c.dy+math.sin(a)*r);}Widget _circle({required Offset center,required bool selected,required String semantics,required VoidCallback onTap,required Widget child})=>Positioned(left:center.dx-24,top:center.dy-24,width:48,height:48,child:Semantics(button:true,label:semantics,child:Material(color:selected?const Color(0xFF6750A4):const Color(0xE6222430),shape:const CircleBorder(),elevation:selected?5:2,child:InkWell(customBorder:const CircleBorder(),onTap:onTap,child:Center(child:child)))));
